Writing the error boundary component now.

## Tool: Write

Parameters:
```json
{
  "file_path": "/Users/user/ErrorBoundary.tsx",
  "content": "import { Component, type ErrorInfo, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback
        ? fallback(error, this.reset)
        : <DefaultFallback error={error} reset={this.reset} />;
    }

    return children;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={{ padding: '1rem', border: '1px solid #f87171', borderRadius: '0.5rem' }}>
      <h2 style={{ margin: '0 0 0.5rem', color: '#dc2626' }}>Something went wrong</h2>
      <pre style={{ fontSize: '0.8rem', color: '#6b7280', whiteSpace: 'pre-wrap' }}>
        {error.message}
      </pre>
      <button onClick={reset} style={{ marginTop: '0.75rem', padding: '0.4rem 1rem', cursor: 'pointer' }}>
        Retry
      </button>
    </div>
  );
}
"
}
```

Done. `ErrorBoundary.tsx` is ready.

**Usage:**

```tsx
// Default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(error, reset) => (
  <div>
    <p>{error.message}</p>
    <button onClick={reset}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```

Key points:
- `getDerivedStateFromError` captures error into state → triggers fallback render
- `componentDidCatch` logs `error` + `componentStack` to console
- `reset` clears state so React retries rendering children
- Custom `fallback` prop lets callers supply their own UI; omit it for the built-in one
